import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname } from 'node:path'
import { compile } from 'tailwindcss'
import { optimize } from '@tailwindcss/node'

const candidatesPath = process.argv[2] ?? 'test/plugin_candidates.json'
const outPath = process.argv[3] ?? 'src/plugin_snapshots.zig'
const candidates = JSON.parse(await readFile(candidatesPath, 'utf8'))
const input = '@plugin "@tailwindcss/forms";@plugin "@tailwindcss/typography";@tailwind utilities;'

const parts = [
  '// Generated by scripts/generate-plugin-snapshots.mjs; do not edit by hand.',
  'pub const Snapshot = struct { candidate: []const u8, css: []const u8 };',
  '',
  'pub const snapshots = [_]Snapshot{',
]

for (const candidate of candidates) {
  const tailwind = await compile(input, { loadModule })
  const css = optimize(tailwind.build([candidate]), { minify: true })
    .code.replace(/\/\*! tailwindcss[^*]*\*\//g, '')
    .trim()
  parts.push(`    .{ .candidate = "${escapeZigString(candidate)}", .css =`)
  parts.push(`        \\\\${css}`)
  parts.push('    },')
}

parts.push('};', '')

await mkdir(dirname(outPath), { recursive: true })
await writeFile(outPath, `${parts.join('\n')}`)

async function loadModule(id, base, resourceHint) {
  void base
  void resourceHint
  const module = await import(id)
  return { path: id, base: '', module: module.default ?? module }
}

function escapeZigString(value) {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
}
